import { BIGX, bigAdd, bigIsVowel, bigMake } from './bigdict.js';
import { LEX, N, V } from './engine.js';
// 動詞ごとの目的語ランキング（よく使う順）。外部AIで作成・check.pyで検証済み（2026-10-12）
// t:/p: は基本語彙のid、n:/P:/A: は大辞書（名詞/人/動物）の語。return は除外（return home の home は副詞のため）
export let OBJRANK;
export let OBJRANK_R; export let OBJRANK_BIG;
export function objRankBig(tag,w){ if(!OBJRANK_BIG){ OBJRANK_BIG={n:{},P:{},A:{}}; [['n','n'],['p','P'],['an','A']].forEach(([k,t])=>(BIGX[k]||[]).forEach(e=>{ const kk=String(e.w).toLowerCase(); if(!OBJRANK_BIG[t][kk]) OBJRANK_BIG[t][kk]=e; })); }
 return OBJRANK_BIG[tag][String(w).toLowerCase()]||null; }
// 動詞id → 目的語ref の配列（よく使う順）。大辞書の語はこの時点でLEXに足す
export function objRankRefs(vid){ if(OBJRANK_R[vid]) return OBJRANK_R[vid]; const L=OBJRANK[vid]; if(!L) return null; const out=[];
 L.forEach(s=>{ try{ const i=s.indexOf(':'), tag=s.slice(0,i), w=s.slice(i+1);
  if(tag==='t'||tag==='p'){ if(!N(s)) return; const vv=V(vid)||{}; const vt=vv.t||[];
   // 動物を取る動詞（feed など）で「食べ物」の語に当たったら、同じ語の動物を使う（chicken＝鶏肉→ニワトリ）
   if(tag==='t'&&vt.includes('animal')&&!vt.includes('food')){ const k=String(N(s).en).replace(/^(a|an|the) /,'').toLowerCase(); const an=LEX.people.find(p=>p.animal&&String(p.en).replace(/^(a|an|the) /,'').toLowerCase()===k); if(an){ out.push('p:'+an.id); return; } }
   out.push(s); return; }
  const e=objRankBig(tag,w); if(!e) return; const k=tag==='n'?'n':tag==='P'?'p':'an'; const r=bigMake(k,e,'obj'); const id=bigAdd(r[0],r[1]); out.push((r[0]==='things'?'t:':'p:')+id);
 }catch(e){} });
 OBJRANK_R[vid]=out; out.set=new Set(out); return out; }
export function objRanked(v,ref){ try{ const L=v&&objRankRefs(v.id); return !!(L&&L.set.has(ref)); }catch(e){ return false; } }

// 大辞書の名詞の数え方（目的語ランキングに出る774語）。c=数える u=数えない C=両方・ふつう数える U=両方・ふつう数えない t=ふつうthe p=ふつう複数形
export let COUNTAB;
export let IRRPL;
export function cntPlural(w){ w=String(w); const lw=w.toLowerCase(); if(IRRPL[lw]) return IRRPL[lw]; if(/(s|x|z|ch|sh)$/i.test(w)) return w+'es'; if(/[^aeiou]y$/i.test(w)) return w.slice(0,-1)+'ies'; return w+'s'; }
// 数え方の印をもとに、目的語として使う形（冠詞・複数）と判定用の印を返す
export function cntForm(w){ const t=COUNTAB[w]; if(!t) return null;
 if(t==='c'||t==='C') return {en:(bigIsVowel(w)?'an ':'a ')+w,cnt:'c',pl:0};
 if(t==='u'||t==='U') return {en:w,cnt:'u',pl:0};
 if(t==='t') return {en:'the '+w,cnt:'u',pl:0};
 if(t==='p'){ const pw=cntPlural(w); return {en:pw,cnt:'p',pl:1}; } return null; }

// 動詞＋目的語ごとの自然な日本語（外部AIで作成）。キー "動詞id|目的語の語" → [名詞, 助詞, 動詞の辞書形, 活用(g/i/s/k/aru)]
export let PAIRJA;
export function pairJa(vid,ref){ try{ if(!vid||!ref) return null; const n=N(ref); if(!n) return null; const k=vid+'|'+String(n.en).replace(/^(a|an|the|my) /i,'').toLowerCase(); const p=PAIRJA[k]; return p?{n:p[0],p:p[1],v:p[2],t:p[3]}:null; }catch(e){ return null; } }


